Ask.message:
{
  "id": "pick-profile",
  "title": "Sound profile",
  "subtitle": "Pick one to adjust",
  "place": "center",
  "width": 340,
  "widgets": [
    {
      "type": "choice",
      "id": "profile",
      "submit": true,
      "options": [
        {
          "value": "Work",
          "label": "Work",
          "hint": "Quiet, notices only"
        },
        {
          "value": "Home",
          "label": "Home",
          "hint": "Everything on"
        },
        {
          "value": "Night",
          "label": "Night",
          "hint": "Nothing makes a sound"
        }
      ]
    }
  ]
}

{
  "id": "edit-profile",
  "title": "Adjust {{profile}}",
  "subtitle": "Changes apply when you save",
  "place": "center",
  "widgets": [
    {
      "type": "input",
      "id": "label",
      "label": "Name shown",
      "hint": "What the profile is called",
      "value": "{{profile}}",
      "required": true
    },
    {
      "type": "slider",
      "id": "volume",
      "label": "Volume",
      "min": 0,
      "max": 100,
      "step": 5,
      "value": 40,
      "unit": "%"
    },
    {
      "type": "choice",
      "id": "theme",
      "label": "Notices",
      "layout": "chips",
      "options": [
        "Quiet",
        "Normal",
        "Loud"
      ],
      "value": "Normal"
    },
    {
      "type": "separator"
    },
    {
      "type": "toggle",
      "id": "advanced",
      "label": "Show advanced options"
    },
    {
      "type": "number",
      "id": "delay",
      "label": "Delay before a notice",
      "min": 0,
      "max": 60,
      "step": 1,
      "value": 0,
      "unit": "s",
      "show_if": {
        "id": "advanced"
      }
    },
    {
      "type": "color",
      "id": "tint",
      "label": "Color of the badge",
      "value": "#3b82f6",
      "show_if": {
        "id": "advanced"
      }
    }
  ],
  "buttons": [
    {
      "id": "cancel",
      "label": "Cancel",
      "cancel": true,
      "side": "start"
    },
    {
      "id": "reset",
      "label": "Reset",
      "tone": "danger"
    },
    {
      "id": "save",
      "label": "Save profile",
      "tone": "primary"
    }
  ]
}
